<?php

$edit=null;if(isset($query['edit'])){$s=$db->prepare('SELECT * FROM hrm_factors WHERE id=?');$s->execute([(int)$query['edit']]);$edit=$s->fetch();}
$rows=$db->query('SELECT * FROM hrm_factors ORDER BY is_outcome DESC,display_order,name')->fetchAll();
echo '<div class="notice">The approved capstone instrument contains one outcome measure, <strong>Employee Retention</strong>, plus eight HRM predictor factors. The outcome measure remains active so retention scores can be calculated separately from HRM perceptions.</div>';
echo '<div class="grid two" style="margin-top:14px"><div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Measure / Factor</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody>';
foreach($rows as $r){$type=(int)($r['is_outcome']??0)?'Outcome Measure':'HRM Factor';echo '<tr><td>'.$r['display_order'].'</td><td><strong>'.e($r['name']).'</strong><br><span class="muted small">'.e($r['description']).'</span></td><td>'.badge($type,(int)($r['is_outcome']??0)?'warn':'neutral').'</td><td>'.badge($r['status'],$r['status']==='active'?'good':'neutral').'</td><td><a class="btn btn-secondary" href="?page=factors&edit='.$r['id'].'">Edit</a></td></tr>';}
echo '</tbody></table></div></div><div class="form-card"><h3>'.($edit?'Edit Measure / Factor':'Add HRM Factor').'</h3><form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.e($edit['id']??'').'"><div class="form-group"><label>Name</label><input name="name" required value="'.e($edit['name']??'').'"></div><div class="form-group" style="margin-top:10px"><label>Description</label><textarea name="description">'.e($edit['description']??'').'</textarea></div><div class="form-grid" style="margin-top:10px"><div class="form-group"><label>Display Order</label><input type="number" name="display_order" value="'.e($edit['display_order']??count($rows)+1).'"></div><div class="form-group"><label>Status</label><select name="status"'.(((int)($edit['is_outcome']??0))?' disabled':'').'><option'.selected($edit['status']??'active','active').'>active</option><option'.selected($edit['status']??'','inactive').'>inactive</option></select>'.(((int)($edit['is_outcome']??0))?'<input type="hidden" name="status" value="active"><span class="muted small">The approved retention outcome cannot be deactivated.</span>':'').'</div></div><button class="btn btn-primary" style="margin-top:12px">Save</button></form></div></div>';

